(function(root){
 const step=(title,actions,expect,help)=>({title,actions,expect,...(help?{help}:{})});
 const lessons=[
 {id:'modes',area:'Find your way',title:'Chat, Work and Codex: choose where to start',minutes:'About 8–12 min',summary:'Locate the controls and choose a starting point for different kinds of task.',source:'quickstart',controls:['ChatGPT/Codex selector','Chat / Work switcher','New chat'],steps:[
 {title:'Three starting points',body:['Chat suits a conversation, such as explaining an idea or drafting a message. Work emphasizes tasks with tools and deliverables. Codex emphasizes development with source files and developer tools.','Capabilities overlap. A mode name does not establish which tools or account permissions you have. This trial requires no repository or account connection.'],expect:'You can choose an initial workspace based on the task.'},
 step('Find the selectors',['Expand the desktop sidebar if needed. Open the product selector and locate ChatGPT and Codex. Select ChatGPT.','Start a new chat. Above the composer, locate the Chat / Work switcher and choose Chat.','Notice the selected labels so you can return to this view.'],'You have located both the product selector and workflow switcher.','If labels differ, use the current Quickstart. Do not change subscription or permissions to make a label appear.'),
 step('Try a conversation',['In Chat, ask for help writing a short invitation to a weekend picnic. Use your own wording.','Read the invitation and request one change, such as a warmer tone or shorter length.','Check the revision against that change.'],'You have tried a conversation without needing a local folder or coding project.'),
 step('Explore the other starting points',['Start a new chat, select Work and inspect its available controls without beginning a connected action.','Select Codex from the product selector and inspect its New chat/project controls. No repository is needed just to inspect them.','Return to ChatGPT → Chat. Choose a starting point for a quick explanation, an editable report and a software change.'],'You can switch views and justify a starting point while recognizing that capabilities overlap.','Record an absent workflow as unavailable for your client, rather than guessing its access.')],transfer:'For your next task, choose the starting point yourself and explain why.'},
 {id:'model-choice',area:'Find your way',title:'Choose a model and reasoning setting',minutes:'About 10 min',summary:'Inspect the choices, compare one small task and restore a sensible default.',source:'models',controls:['Model / Power control','Advanced','Reasoning effort'],steps:[
 {title:'Choose for the task',body:['A model produces the response. Reasoning effort controls how much thinking work a supported model puts into a request. Higher effort can take longer and use more allowance; it does not guarantee a better answer.','Use choices your account actually exposes. No particular model or purchase is required.'],expect:'You can explain why a quick rewrite and a difficult analysis might need different settings.'},
 step('Inspect the current selection',['Open a new Work or Codex chat. Find the model/reasoning or Power control beneath the composer.','Note the current selection. Open Advanced if your client offers presets plus advanced choices.','Read the available model and effort labels without assuming another account’s choices apply.'],'You can locate the control and identify actual available settings.','If only one option exists, inspect it and do one run. Do not claim a comparison without two selectable configurations.'),
 step('Compare a fair example',['Write a six-item weekend to-do list and ask for a three-step plan. Keep that input identical for both runs.','Run it in a fresh chat with the current/default setting. Check whether all items were preserved.','In another fresh chat, choose a second available configuration. Compare usefulness, omissions and observed waiting time.'],'You have comparable outputs. One example does not prove universal superiority or savings.'),
 step('Restore and apply your judgment',['Restore the earlier/default selection if you do not want to keep the experiment’s choice.','Choose a real task for today. Decide whether speed, deeper reasoning or a particular tool matters most.','Check the selected configuration before starting.'],'You can change and restore the control without confusing it with permissions.')],transfer:'Choose a setting for a real task and report only usage or savings you actually measured.'},
 {id:'steer-chat',area:'Find your way',title:'Steer a response and stop unwanted work',minutes:'About 7–10 min',summary:'Stop a text response, correct its direction and request one focused revision.',source:'settings',controls:['Composer','Stop','Follow-up behavior'],steps:[
 {title:'A request can change direction',body:['A useful AI skill is noticing what is wrong and naming a concrete correction. Stop ends generation; it does not undo actions already performed.','Use text-only work so an interruption cannot leave an important file edit unfinished.'],expect:'You distinguish stopping generation, requesting a revision and undoing an external action.'},
 step('Interrupt safely',['Ask in a new chat for a detailed ten-part plan for a fictional community picnic.','While it generates, locate and select Stop. If it finishes too quickly, try a longer text-only response.','Inspect the partial answer and notice that text already produced remains.'],'You used the actual Stop control, rather than only typing the word Stop.','Do not learn interruption on a task editing important files.'),
 step('Give a useful correction',['Ask for only three actions suitable for a rainy indoor picnic.','Check both the length and setting; name the exact omission if either was missed.','In supported Work/Codex clients, inspect Settings → General → Follow-up behavior to see whether messages steer the active run or wait. Keep the setting unless you choose to change it.'],'You can give a specific correction and inspect active-run behavior.'),
 step('Revise only one part',['Choose one item to replace and say which parts should stay the same.','Compare the revision with the previous answer.','For an external action, inspect what actually happened before choosing any targeted undo.'],'You can refine a result without discarding parts that work.')],transfer:'Correct one real response by naming a specific change.'},
 {id:'attachments',area:'Everyday tasks',title:'Attach a file and check what ChatGPT read',minutes:'About 10 min',summary:'Upload a small note, question its contents and verify the answer.',source:'files',controls:['+ / attachment control','File picker','Attachment preview'],steps:[
 {title:'A filename is not an upload',body:['An attachment supplies actual file contents through supported reading tools. Typing a local path does not upload that file.','Use a small harmless shopping note so you know exactly what an accurate answer should contain.'],expect:'You can identify the supplied file and check an answer against it.'},
 step('Prepare a verifiable file',['In Notepad, write three lines: Apples 4; Rice 1 bag; Tea 2 boxes.','Save it as shopping-note.txt in a practice folder and reopen it to check the contents.','Return to a new ChatGPT chat.'],'You have a real file whose exact contents you know.'),
 step('Use the attachment control',['Open the + or attachment control beside the composer and choose its file-attachment option.','Select shopping-note.txt. Wait for the attachment preview/indicator and check its filename.','Ask which items need more than one unit, using only the attached note.'],'The intended file is attached and the answer identifies Apples and Tea.','Pasting text is a useful alternative when upload is absent, but does not demonstrate file upload.'),
 step('Check the boundary',['Compare the quantities with your actual local file.','Ask whether the note gives a shopping date. It should identify that no date was supplied.','If it invents a date or misses an item, point to the relevant line and request a correction.'],'You can distinguish a read attachment from a guess and detect unsupported details.'),
 step('Use your own file',['Attach another small non-sensitive file in a fresh chat and choose a question you can verify.','Compare the answer with its source. Narrow the question or provide a clearer excerpt if reading is poor.','Keep your local file; removing an attachment from an unsent draft does not delete a file on disk.'],'You can repeat attachment and verification independently.')],transfer:'Try a recipe, agenda or public handout and choose your own checkable question.'},
 {id:'projects',area:'Organize work',title:'Create a Project for an ongoing task',minutes:'About 12–15 min',summary:'Make a planning project and test shared sources in two chats.',source:'projects',controls:['Projects','Create project','Sources','Chats'],steps:[
 {title:'Group work that continues',body:['A project groups related chats, sources and instructions for ongoing work such as planning a trip or studying a subject.','An uploaded-source ChatGPT project and a local project linked to a folder are different. This trial uses the former and harmless planning material.'],expect:'You know why to use a project without assuming access to your whole PC.'},
 step('Create the trial',['Open Projects and its project-creation control. Choose a ChatGPT project where that choice is offered.','Name it Weekend planning trial. Inspect scope/sharing choices and keep this personal trial private.','Open it and locate Chats and Sources.'],'The intended project exists and you can locate its chats and sources.','If only a local-folder route is offered, do not silently treat it as an uploaded-source project. Consult the Projects guide or mark this route unavailable.'),
 step('Add a source',['In Sources, add a short text/file note: Saturday morning is free; plan indoors if it rains; no car is available.','Inspect the added source’s actual contents.','Start a chat inside the project and ask for two activity ideas respecting these constraints.'],'The source is in the project and the suggestions can be checked against it.'),
 step('Try a separate project chat',['Start another chat from this project and request a preparation checklist for an indoor Saturday activity.','Compare its answer with the shared source; ask which source supports the constraints if unclear.','Shared sources do not prove the entire transcript of another chat transferred.'],'You can reuse project context and inspect its evidence.'),
 step('Return to your work',['Rename the two chats so their outcomes are recognizable.','Leave and reopen the project, then find both chats and the source again.','Keep this trial for the instructions lesson; archive later if desired. Do not delete unrelated projects.'],'You can create, populate and return to a project.')],transfer:'Choose an ongoing task and decide what belongs in project sources versus one chat.'},
 {id:'project-instructions',area:'Organize work',title:'Make project instructions do a specific job',minutes:'About 8–12 min',summary:'Set a project rule, test it across chats and revise it.',source:'projects',controls:['Project menu / settings','Project instructions','New project chat'],steps:[
 {title:'Information and guidance differ',body:['A source provides information. Instructions guide behavior. A project rule is useful when the same requirement should apply to several chats in that project.','Use the disposable Weekend planning trial project, not an unrelated work project.'],expect:'You distinguish source information from a behavioral rule.'},
 step('Store a small rule',['Open the trial project’s menu/settings and its project instructions control.','Add: For this project, end activity suggestions with a heading called Next small action and one concrete action.','Save and reopen the instructions to check the stored rule.'],'The rule is in project instructions rather than only a chat message.','If this editor is missing, consult current project help; do not replace it with an account-wide rule without choosing that different scope.'),
 step('Test without repeating it',['Start a fresh chat inside the project and ask for an indoor activity idea without repeating the rule.','Inspect the requested heading/action. If missing, inspect the saved instructions and chat membership.','Try a different activity question in another fresh project chat.'],'You compared responses with a stored rule; an answer alone cannot prove the source of an instruction.'),
 step('Revise and clean up',['Change the trial rule to request a short numbered list, then save and test a fresh project chat.','Compare the result with the earlier format.','Remove only your trial rule if you do not want to keep it; preserve prior instructions.'],'You can edit and remove a project rule within the intended scope.')],transfer:'Choose a repeated requirement and put it in the narrowest supported scope.'},
 {id:'image-create',area:'Everyday tasks',title:'Create an image you can actually use',minutes:'About 10–15 min',summary:'Create a picnic illustration, inspect it, revise one detail and save it.',source:'imageGeneration',controls:['Composer','Image viewer','Focused / Canvas view','Save / download'],steps:[
 {title:'Define a visual outcome',body:['Image generation produces actual images for uses such as invitations, illustrations and mockups.','Start with a picnic invitation illustration without text. Choose the setting, objects, style and shape yourself.'],expect:'You can name what would make the image useful.'},
 step('Create a first image',['Start an image-capable chat. Describe your chosen picnic scene and ask for the actual image.','For example, choose a square illustration featuring a basket under a tree; use your own details.','Wait for the result and open the actual image.'],'An image is displayed and its visual details can be checked.','Prose describing an image is not image generation. Check availability if no actual image is produced.'),
 step('Inspect in the viewer',['Select the image to open its expanded viewer.','Try Focused view for one image and Canvas view for images in the same chat, where offered.','Inspect composition, shape and unexpected details. Choose one specific improvement.'],'You inspected the actual image rather than only accepting its thumbnail.'),
 step('Change one detail',['Request one change, such as replacing the tree with a parasol while keeping the basket and style.','Compare the revised image with the original.','If supported, use image comments to point at the area; otherwise describe its location clearly.'],'You checked both the intended change and what remained the same.'),
 step('Save and use it',['Use the viewer’s save/download control and choose a location/name.','Open the saved file and keep the original version until you are satisfied.','Create another visual for a purpose you choose.'],'You have an accessible image and can repeat the process.')],transfer:'Make an invitation, study visual or personal-project illustration and judge it against your own requirements.'},
 {id:'image-edit',area:'Everyday tasks',title:'Edit an existing image and keep the original',minutes:'About 10 min',summary:'Attach a source, change one detail and compare the actual files.',source:'imageGeneration',controls:['Image attachment','Image viewer','Comments / selected area','Save / download'],steps:[
 {title:'Editing needs a source',body:['Editing transforms an image you supply. Asking for a similar scene without the source is a different task.','Use the picnic image or a non-sensitive image you own. Preserve its original file.'],expect:'You know which image is the source and what must stay unchanged.'},
 step('Attach the intended image',['In an image-capable chat, attach the source and inspect its preview.','Choose one change, such as the basket color. State which objects, framing and style should remain.','Send the edit request with the attachment.'],'The task uses the intended source.','If multiple images exist, identify the source explicitly. If edits are unsupported, record that rather than treating an unrelated new image as an edit.'),
 step('Compare the result',['Open the revised image and compare the changed area and nearby details with the original.','Identify unwanted drift as well as the requested change.','Use a supported comment/selection or clearer area description to repair just the mistaken edit.'],'You can point to the actual difference and assess what stayed intact.'),
 step('Save separately',['Save/download under a different filename and open both files once.','Verify that the original remains and the edited file is the intended version.','Choose a small useful edit to another image you own.'],'You can repeat a controlled edit while preserving its source.')],transfer:'Before editing your own image, name exactly what may change and what must remain.'}
 ];
 lessons.push(
 {id:'web-search',area:'Everyday tasks',title:'Search the web and inspect the sources',minutes:'About 10–12 min',summary:'Find current public information, open its evidence and check a practical decision.',source:'webSearch',controls:['Composer','Search activity','Citations / source links'],steps:[
 {title:'Choose a question needing current evidence',body:['Web search helps with information that may have changed. Sources are evidence to inspect, not a guarantee that the answer is correct.','Choose a public museum or library and a particular date. You will check official opening hours without providing a private address or signing in.'],expect:'You have a concrete question with a checkable official source.'},
 step('Request a search and watch activity',['Ask in a new chat for the named place’s hours on your chosen date, with an official source.','Inspect the transcript’s search activity and cited links.','Check the place and date; do not assume every day has the same hours.'],'You can identify actual search activity and the source behind the answer.','If search is unavailable, open the page manually and label that route. A remembered answer is not current research.'),
 step('Open the strongest citation',['Open the official source and find the passage giving hours, exceptions or closures.','Compare its place, date and times with the chat answer.','If the link lacks the claim or refers to another place, point out the mismatch and request a correction.'],'You verified evidence instead of merely counting citations.'),
 step('Use it in a decision',['Ask whether a two-hour visit fits before closing, using the verified hours.','Check the time calculation yourself.','Choose one real question of your own that needs fresh information and identify an authoritative source.'],'You can turn researched information into a checked decision.')],transfer:'Research a current, non-sensitive question and open its strongest supporting source.'},
 {id:'browser-tabs',area:'See and work',title:'Use an in-app browser beside the chat',minutes:'About 8–12 min',summary:'Open a public page, arrange the view and check which tab ChatGPT read.',source:'browser',controls:['New tab','Address bar','Enter full view','Enter split view'],steps:[
 {title:'Identify this browser',body:['The in-app browser has its own profile. It does not automatically inherit regular-browser tabs or sign-ins.','Use a public page. Connecting your existing Chrome or Edge session is a separate extension route.'],expect:'You can distinguish the in-app browser from a connected regular browser.'},
 step('Open a tab',['Select New tab, or use Ctrl+T when the built-in browser is available.','Enter https://learn.chatgpt.com/docs/use-chatgpt in its address bar.','Inspect the URL and page heading. No sign-in is needed.'],'The public page is identifiable inside the app.','If unavailable, consult Settings → Browser and the Browser guide. An external browser window is not an in-app tab.'),
 step('Arrange your workspace',['Use Enter full view to inspect the page, then Enter split view to place it beside the chat.','Try Ctrl+Shift+B where supported to change the arrangement.','Return to split view for comparison.'],'You can move between views and keep a reference beside the conversation.'),
 step('Check the page being read',['Ask for a summary of one heading in your selected tab.','Compare it with the page and identify the actual tab/URL used.','If another page was read, explicitly identify the intended tab and retry.'],'The answer matches the intended page rather than guessing from its URL.'),
 step('Manage the tabs',['Open another public page in a second in-app tab, then return to the first.','Close only the test tabs you no longer need.','Choose a real reference-reading task for split view.'],'You can identify, arrange and close the tabs yourself.')],transfer:'Keep a public reference beside the chat and verify a summary against it.'},
 {id:'voice',area:'Speak and personalize',title:'Have a voice conversation and end it',minutes:'About 5–8 min',summary:'Start a spoken exchange, steer it and stop voice yourself.',source:'voice',controls:['Start voice chat','Start new voice chat','Stop voice chat'],steps:[
 {title:'Voice is a conversation',body:['Voice supports a spoken back-and-forth. Dictation turns speech into editable message text and has its own lesson.','Use a quiet place and harmless topic. You choose whether to grant microphone access. No screen sharing is needed.'],expect:'You know whether you are testing a spoken conversation or text entry.'},
 step('Start talking',['Open a supported chat/task and select Start voice chat or Start new voice chat.','If prompted, decide whether to allow the microphone and choose a voice.','Ask aloud for an easy indoor hobby idea.'],'You hear an actual spoken reply.','If absent, check availability and whether another voice chat is already active. Dictated text is not a substitute voice conversation.'),
 step('Steer the exchange',['Ask a spoken follow-up about trying that hobby in fifteen minutes.','Interrupt with one concrete correction, such as using only materials you own.','Check that the next answer reflects the change.'],'You experienced turn-taking and steering rather than only playing audio.'),
 step('End the session',['Select Stop voice chat and verify its controls no longer show active listening.','Return to the main chat and inspect any transcript/result your client provides.','Decide when speaking would help and when text would be easier to review.'],'You can start, steer and end voice independently.')],transfer:'Brainstorm your own small task aloud, then end voice yourself.'},
 {id:'dictation',area:'Speak and personalize',title:'Dictate, correct and send a message',minutes:'About 4–6 min',summary:'Turn speech into text while controlling exactly what gets sent.',source:'voice',controls:['Dictation control','Composer','Send'],steps:[
 {title:'Talk into the composer',body:['Dictation is useful when speaking is easier than typing but you still want to inspect the wording before sending. It is different from live voice conversation.'],expect:'Your target is editable text in the composer.'},
 step('Try dictation',['Find the dictation/microphone control in a new chat. Read its label so you do not start a voice call instead.','If you choose microphone access, dictate: Help me plan a quiet weekend afternoon.','Finish using the displayed control and inspect the text before sending.'],'Your spoken sentence becomes editable text.','If only live voice is available, record dictation unavailable. Do not assume the two controls do the same thing.'),
 step('Correct, then send',['Correct a misrecognized word and add a typed detail, such as a time limit.','Read the final message and choose Send yourself.','Inspect the reply and decide whether dictation helped.'],'You controlled the exact text sent and completed the whole dictation/edit/send cycle.')],transfer:'Dictate a longer non-sensitive request and check names, numbers and intent before sending.'},
 {id:'chat-management',area:'Organize work',title:'Rename, find, pin and archive a chat',minutes:'About 8–10 min',summary:'Keep useful conversations retrievable and restore an archived trial.',source:'projects',controls:['Chat menu','Rename','Pin','Search chats','Archive','Unarchive'],steps:[
 {title:'Organize without losing work',body:['Names and pins make useful work easier to find. Pinning changes visibility, not AI context or permissions. Archiving is different from deleting.'],expect:'You can organize a trial conversation without deleting real work.'},
 step('Rename and find',['Create a harmless chat about weekend hobbies. Use its menu to rename it Hobby ideas — trial.','Use Search chats or the available search control to find it by title or a memorable phrase.','Open the actual result and check it is the intended conversation.'],'You can retrieve work without scrolling every chat.'),
 step('Pin and unpin',['Pin the trial through its chat menu and inspect its sidebar position.','Reopen it and verify the messages are unchanged.','Unpin if you do not want to keep it at the top.'],'You changed visibility without treating a pin as memory or added context.'),
 step('Archive and restore',['Archive only Hobby ideas — trial.','Open Settings → Archived chats in the desktop app, find it and select Unarchive. Some clients put archives under Data Controls.','Open the restored conversation and check its messages. Do not select Delete for this trial.'],'You completed a reversible organization cycle.')],transfer:'Name two useful chats clearly and decide which one deserves a pin.'},
 {id:'app-settings',area:'Find your way',title:'Find settings and make the app comfortable',minutes:'About 6–8 min',summary:'Inspect input behavior and shortcuts and try one reversible appearance change.',source:'settings',controls:['Settings','General','Appearance','Keyboard Shortcuts'],steps:[
 {title:'Preferences affect your interface',body:['A font, theme or send-key preference changes how you use the app, not the model’s ability or feature permissions.','Account, security, privacy and memory have separate controls; this trial uses only everyday preferences.'],expect:'You understand what a chosen preference will affect.'},
 step('Inspect settings',['Open Settings from the app menu or press Ctrl+, on Windows.','In General, inspect the Enter/send behavior and note its current value.','In Keyboard Shortcuts, find New chat and read the binding configured on your machine.'],'You can locate a preference and an actual configured shortcut.'),
 step('Try and restore a change',['In Appearance, choose another base theme or adjust the UI font size slightly.','Return to the chat and inspect the visible effect.','Restore the earlier value if preferred, or deliberately keep your choice.'],'You can change and restore an everyday preference.'),
 step('Use one discovered shortcut',['Use the New chat binding you inspected, or another harmless navigation shortcut.','Check the result. If it differs, inspect its custom binding in Keyboard Shortcuts.','Leave unrelated account and permission settings alone.'],'You used a real configured control rather than memorizing another platform’s shortcut.')],transfer:'Choose one helpful preference and one shortcut you will actually use.'},
 {id:'codex-memories',area:'Organize work',title:'Inspect Codex memory scope and chat choices',minutes:'About 8–12 min',summary:'Find local memory controls and distinguish them from ChatGPT memory and explicit context.',source:'memories',controls:['Settings → Personalization','Enable Codex memories','/memories'],steps:[
 {title:'Identify the memory store',body:['Codex local memories and ChatGPT memory are separate. Local memories belong to the selected host; ChatGPT Work follows its account/workspace memory settings.','Do not test this by deleting memories or switching accounts. Required project instructions and attached notes are also distinct from automatic recall.'],expect:'You can name the product and host whose memory you are inspecting.'},
 step('Inspect the machine setting',['In the Codex desktop view, open Settings → Personalization and locate Enable Codex memories if available.','Read its state and any tool-assisted-chat contribution setting. Keep them unless you deliberately choose a change.','Record absent controls as unavailable, not proof that another memory store is enabled.'],'You inspected the actual machine-level setting.','For ChatGPT Work, use its own Personalization/memory controls; do not assume this local Codex setting applies.'),
 step('Inspect the chat choices',['Enter /memories in a supported Codex chat and inspect use/contribution choices.','If memory is already enabled and you choose to test a per-chat option, note its value, change only that trial chat’s choice and reopen the control to check it.','Restore the original chat choice if wanted. Do not use Delete Codex memories for this exercise.'],'You distinguish per-chat choices from machine settings. If unavailable, you do not claim to have changed them.'),
 step('Compare with supplied context',['Supply a harmless fictional note that a trial project is named Sunflower and request a one-sentence recap.','Identify that the name came from your message; that is not proof of automatic recall.','Keep exact requirements in explicit records. Memory generation is background work and may not update immediately.'],'You can state what was observed and what remains unproved.')],transfer:'Decide which real guidance must stay explicit and which optional recall setting you want to inspect.'},
 {id:'pets',area:'Speak and personalize',title:'Use a Pet and floating Mini controls',minutes:'About 6–10 min',summary:'Choose a companion, start a harmless chat and hide the overlay.',source:'pets',controls:['Settings → Pets','Mini','/pet','Show pet','Hide'],steps:[
 {title:'An interface companion',body:['Pets provide floating controls and activity cues. Their appearance does not change the model’s intelligence. Mini can show floating controls without a pet.','Use an existing built-in pet; creating a custom one is a separate lesson.'],expect:'You know which part of the interface changes.'},
 step('Choose and show',['Open Settings → Pets, or the profile menu’s Pets entry. Note the current choice.','Choose a built-in pet. Enter /pet in its supported context or use Show pet in the command menu.','Inspect the floating controls. Try Mini if offered and observe the controls without a companion.'],'You identify the actual overlay and Mini selection.','If unavailable or blocked by the workspace, do not claim the overlay ran.'),
 step('Use the controls',['Point below the pet and select its pencil/start-chat control.','Ask a harmless hobby-planning question and inspect the resulting chat in the main app.','Try the bell/activity control if present. Chats started here are outside a project.'],'You can start and locate a real chat and understand its project boundary.'),
 step('Hide and restore',['Right-click the pet and select Hide, or use Hide pet from the command menu.','Verify it is hidden and restore the earlier selection in Settings → Pets if desired.','Choose whether these controls help your normal work.'],'You can manage the overlay without leaving an unwanted change.')],transfer:'Use the overlay for a quick question and the main project view when project context matters.'}
 );
 lessons.push(
 {id:'plus-menu',area:'Find your way',title:'Use the + menu without sending the wrong context',minutes:'About 5–8 min',summary:'Explore your available entries, attach a harmless file and remove it before sending.',source:'files',controls:['+ / Attach','Attachment preview','Remove attachment','Escape'],steps:[
 {title:'A menu of available actions',body:['The + menu beside the message box offers context or actions available in your current chat. Its entries can differ between modes and accounts.','You will inspect your menu, then practice selecting and removing a file. You do not need to try every entry today.'],expect:'You know that the menu belongs to the current chat and can change with its capabilities.'},
 step('Open and close the menu',['Start a disposable chat. Locate + or the attachment control beside the message box and open it.','Read the entries actually present. Identify the file/image attachment entry; leave account connections and other setup for their own tutorials.','Close the menu with Escape or a click outside it, then reopen it.'],'You can find and dismiss your actual menu.','If your layout has a paperclip or Attach instead, use that control. An absent entry is not a reason to change your subscription.'),
 step('Select, inspect and remove',['Create a small text file in Notepad containing a fictional picnic item and save it as picnic-trial.txt.','Use the attachment entry to select it. Check its name in the composer before sending.','Use the attachment’s remove control. Verify the file is no longer selected. This removes the draft attachment, not your original local file.'],'You can catch a wrong selection before sharing it.'),
 step('Use the selection deliberately',['Attach the intended trial file again, check its name and send a request to list its picnic item.','Compare the answer with your file. Reopen + and identify where you would return for another attachment.','Keep or remove your own local trial file as you prefer.'],'You have used one menu entry end to end and can locate it again.')],transfer:'Before your next real attachment, inspect the selected file and remove anything the task does not need.'},
 {id:'fresh-chat',area:'Organize work',title:'Carry the right context into a fresh chat',minutes:'About 8–12 min',summary:'Restart a picnic-planning task with a short handoff and verify which details were supplied.',source:'projects',controls:['New chat','Project selector','Composer','Earlier chat'],steps:[
 {title:'A fresh conversation needs deliberate context',body:['A new chat starts a separate conversation. Project context, instructions and enabled memory may still apply; new does not mean all other context is erased.','Use a fictional picnic with three decisions: four people, a budget of 40 and no oven. You will carry only those useful decisions into another chat.'],expect:'You distinguish conversation history from other sources of context.'},
 step('Make decisions in the first chat',['Open a trial chat and work out a picnic menu using the three constraints.','Read the result and choose one menu. Write a short handoff yourself: objective, constraints, chosen menu and the next action.','Keep the first chat available so you can compare details.'],'Your handoff contains decisions rather than a long unfiltered transcript.'),
 step('Start and identify the new chat',['Select New chat. Check its product/mode and whether a project is selected.','If you want the same project sources, choose that project deliberately. For a standalone trial, use the available chat outside a project.','Paste your handoff and ask for a shopping list. Do not assume the previous conversation was supplied automatically.'],'You can identify the new chat and the context you explicitly added.','An answer recalling a detail does not prove that it read the old chat. Check project sources and memory settings before drawing that conclusion.'),
 step('Check and repair the handoff',['Compare the shopping list with the people, budget, equipment and chosen menu in your handoff.','If one detail was missing from your handoff, add it and inspect the revision.','Choose whether to continue this chat or return to the first one for the original discussion.'],'You can resume a task from a small explicit record and correct a missing constraint.')],transfer:'For your next separate task, bring its goal, decisions, necessary sources and next action into a new chat.'},
 {id:'screenshots',area:'See and work',title:'Ask about a screenshot and verify what AI can see',minutes:'About 8–10 min',summary:'Capture a harmless window, attach the image and check the answer against visible evidence.',source:'imageInputs',controls:['Windows snipping tool','Paste / image attachment','Image preview','Follow-up correction'],steps:[
 {title:'Show the relevant visible evidence',body:['An image input lets ChatGPT inspect a picture or screenshot. It does not by itself provide control of the app or its hidden content.','Use Notepad with a fictional packing list: water, sandwiches and blanket. Keep private windows outside your capture.'],expect:'You know which visible information you intend to share.'},
 step('Capture and inspect',['Open your fictional packing list in Notepad at a readable size. Use Windows + Shift + S and capture just that region.','Paste the capture into an image-capable chat, or save and attach it using the image/file control.','Inspect the preview: all three items should be legible and unrelated content excluded.'],'The intended image is attached with readable evidence.','If clipboard paste fails, save the capture as an image and attach that file. Retake a blurred or cropped capture before sending.'),
 step('Use the actual image',['Ask which packing items are visible and what one useful item you might add. Use your own wording.','Compare the stated visible items with the screenshot. Separate an observed item from a suggestion.','Ask where a questionable reading appears in the image; correct it or provide a clearer crop if needed.'],'You verified the reading instead of treating a plausible answer as visual proof.'),
 step('Recognize the boundary',['Ask whether the picture shows the contents of another window or text below the captured region. Check whether the answer acknowledges what is absent.','Change an item in Notepad. Notice that the old attachment remains an old capture.','Send a new capture only if the changed screen matters to your next question.'],'You understand that a screenshot is a snapshot, not a live app connection.')],transfer:'Capture a non-sensitive error or confusing control and ask about the visible evidence; verify the reading before acting.'},
 {id:'chatgpt-memory',area:'Organize work',title:'Inspect and manage ChatGPT memory',minutes:'About 8–12 min',summary:'Find the account’s memory controls, inspect a harmless preference and understand its scope.',source:'memories',controls:['ChatGPT settings','Personalization','Memory controls','New chat'],steps:[
 {title:'Choose the right memory controls',body:['Memory can carry useful information between conversations. ChatGPT account/workspace controls are separate from the local Codex memory store.','Use a harmless preference, such as preferring short recipe lists. Keep required task details in explicit instructions too.'],expect:'You know which product’s memory you are inspecting.'},
 step('Inspect before changing',['In the ChatGPT view, open Settings → Personalization and inspect the memory controls available to your account/workspace.','Note their current state and open a memory-management view if offered. Distinguish it from Enable Codex memories for a selected machine.','Keep existing settings unless you deliberately want to change them.'],'You located the relevant controls.','If your client does not expose them, inspect the same account’s ChatGPT web settings. If neither offers access, record unavailable rather than changing local Codex controls.'),
 step('Try a harmless preference',['If memory is already enabled or you choose to enable it, ask ChatGPT to remember your trial recipe-list preference.','Inspect the memory-management view, where available, for the saved item. A conversational acknowledgement alone is not evidence that a memory was saved.','In a fresh chat, ask for a simple recipe list and compare the format. Record what happened without assuming memory was the only possible cause.'],'You distinguish a visible saved record from an inference about a reply.'),
 step('Manage the trial only',['If a trial memory was visibly created and an individual remove control is offered, remove only that item if you do not want it kept.','Reopen the management view to verify the change; avoid clearing other memories. Restore a setting only if you changed it for this trial.','Keep any important recipe requirements explicit in future requests.'],'You can manage the trial within the controls your account provides.')],transfer:'Choose one harmless preference you want remembered, inspect its actual controls, and keep essential task requirements explicit.'},
 {id:'plan-mode',area:'Find your way',title:'Review a plan before implementation',minutes:'About 10–15 min',summary:'Use the Plan control for a small developer task, refine the approach, then explicitly start implementation.',source:'prompting',controls:['Codex composer','/plan','Plan review','Implementation choice'],steps:[
 {title:'Decide the approach before changes',body:['Plan mode helps Codex investigate a task and propose an approach before editing. It is useful when the requested outcome still needs decisions.','Use a new empty practice folder for a small personal packing checklist page. The intended result is one local HTML file with checkboxes and a reset control; nothing needs publishing.'],expect:'You have a small outcome and a reason to review its approach first.'},
 step('Select Plan and describe the outcome',['In File Explorer, create a new empty folder named Packing Trial. In the desktop Codex view, use Open folder to select it and start a chat there.','Type /plan and select the available Plan command. Check the mode indicator.','Describe the checklist page, its controls and the local-only boundary. Request an approach before implementation. Answer any clarifying questions and read the proposed plan.'],'You deliberately selected the planning control and received an approach.','If /plan is missing, inspect the current slash menu in a supported Codex chat. Asking for a written plan is useful, but does not prove Plan mode was selected.'),
 step('Change and assess the plan',['Require keyboard-usable checkboxes and a reset control that clears only this page’s checks.','Check that the revised plan includes how to open the file and test both controls.','Ask for a revision if it proposes deployment, external services or dependencies you do not need.'],'You can identify scope, decisions and a practical verification method before edits.'),
 step('Start implementation deliberately',['Use the offered implementation choice, or toggle /plan off where supported, and explicitly request implementation of the agreed plan.','Inspect the resulting file in the practice folder and open it. Tick an item, use Reset and try the controls from the keyboard.','If the behavior differs from the plan, describe the observed mismatch and inspect the repair.'],'You reviewed an approach and then verified an actual implementation, with the change in mode made deliberately.')],transfer:'Use Plan when an outcome has unresolved choices; read and refine the proposed approach before authorizing implementation.'},
 {id:'usage',area:'Find your way',title:'Read context and usage without confusing them',minutes:'About 5–8 min',summary:'Locate session context and account allowances, then choose a sensible next action.',source:'pricing',controls:['/status','Context indicator','/usage','Usage dashboard'],steps:[
 {title:'Two different limits',body:['Context is the information available to a conversation’s current model run. Tokens are pieces of text/data used to measure model input and output. Account usage is an allowance shared according to your plan and features.','A nearly full conversation and a nearly used account allowance need different responses. Starting a new chat does not replenish the account allowance.'],expect:'You can explain the difference between conversation capacity and an account limit.'},
 step('Inspect session context',['In a supported desktop Work/Codex chat, open /status and inspect the session context information offered.','Look for the composer’s context indicator if available. Read whether a number means used or remaining.','Note the label and value without assuming a missing indicator means unlimited capacity.'],'You can identify the meaning of a context reading.','Slash commands vary by surface. Use the desktop command list; do not copy CLI-only billing/reset commands into this trial.'),
 step('Inspect account allowance',['Open /usage where available, or the account’s usage dashboard through its settings.','Read each available allowance window, its used/remaining label and reset time. Note the displayed timezone or convert it deliberately.','Do not purchase credits or change plans for this exercise.'],'You can find your actual allowance and reset information; unavailable values remain unknown.'),
 step('Choose what to do next',['For a long conversation, prepare a short record of decisions and sources before starting a separate task.','For a low account allowance, reduce the next task’s scope or wait for its displayed reset; opening another chat does not create more allowance.','Choose one real upcoming task and explain which reading, if any, affects your next action.'],'You can act on the relevant limit without guessing a fixed number of messages or a precise token bill.')],transfer:'Check the relevant indicator when planning a longer task and preserve useful decisions before changing chats.'}
 );
 lessons.push(
 {id:'goals',area:'Find your way',title:'Start, pause and finish a Goal',minutes:'About 12–18 min',summary:'Set a bounded local outcome, inspect its progress and verify the actual result.',source:'goals',controls:['/goal','Goal progress row','Pause / Resume','Edit / Clear'],steps:[
 {title:'Give continuing work a finish line',body:['A Goal keeps an objective active across steps. It needs an outcome, boundaries and a way to check completion. A schedule runs work at a chosen time; this trial starts now.','Use an empty practice folder for a packing checklist page. The finish line is one local HTML file with five checkboxes, a count of checked items and a Reset button. No publishing or external accounts are needed.'],expect:'You can describe what must be true before this task is finished.'},
 step('Start the Goal',['Create a new empty Goal Trial folder in File Explorer. Open that folder in a desktop Codex chat.','Enter /goal and use the offered control to set the checklist outcome, the local-only boundary and the three behaviors to verify.','Inspect the goal text and progress row above the composer. Check that it describes the intended task.'],'The objective is visible in an actual Goal control.','If no Goal control appears, inspect the slash menu in your supported client. An ordinary request to keep working is not evidence that Goal mode started.'),
 step('Try the running controls',['While the goal is active, select Pause in its progress row. Inspect the displayed state and any operation already in progress; pausing does not undo finished edits.','If the task finishes before you can pause, keep its result. Use one small follow-up Goal to add a visible page title so you can try the control without repeating the whole build.','Inspect Edit for the goal text and make a small clarification if needed. Resume when ready and observe its state.'],'You can distinguish paused work from completed work and know how to resume.','A short goal may finish too quickly to test every control. Record which controls you actually tried; do not claim to have paused a completed goal.'),
 step('Check the finish line',['Open the generated HTML file from the practice folder. Tick two boxes and check that the count becomes two; use Reset and verify zero checked items.','Compare the file and behavior with the goal criteria. Report an observed mismatch in the same chat if repair is needed.','Inspect the final goal state. Use Clear if you want to remove the goal record from the active controls; this does not delete its output file.'],'You checked the deliverable instead of treating a completed status as proof.')],transfer:'Choose one bounded task with measurable completion criteria. Use a Goal only when you want it to continue toward that outcome.'},
 {id:'permissions',area:'Find your way',title:'Read permission controls and review an action',minutes:'About 8–12 min',summary:'Inspect the current boundary, perform a harmless read and evaluate any approval that actually appears.',source:'approvals',controls:['Permission / approval control','Requested action details','Approve / Decline','Activity result'],steps:[
 {title:'Access and approval answer different questions',body:['The sandbox limits what tools can access. Approval policy determines which actions need review; automatic review can evaluate eligible requests. A connected service also has its own account access.','This trial reads one fictional file in a practice folder. It does not require full access, a network exception or a deliberately risky action to make a dialog appear.'],expect:'You distinguish an access boundary from a request to approve a particular action.'},
 step('Inspect the selected policy',['In a local Work/Codex practice chat, open its available permission or approval control near the composer.','Read the selected mode and scope. Inspect explanatory text for manual versus automatic review, where offered. Keep the current value.','Identify the selected folder/host and any visible writable scope. If the UI omits detail, consult its current official reference rather than inventing a value.'],'You can describe the controls your actual chat exposes.','Managed settings may be read-only or absent. Do not edit config files or broaden access just to complete the trial.'),
 step('Inspect a real action',['Use Notepad to save trial.txt with a fictional packing item inside the practice folder. Ask the chat to read that file and report its item, with no edits.','Inspect the action or activity details. If approval appears, read the action, target and scope before deciding. Decline an action that differs from the requested read; approve only if you want the displayed read to proceed.','If an automatic review appears, inspect its result. If no approval is required, note that the action ran under the existing policy.'],'You can explain what actually ran and whether it was manually reviewed, automatically reviewed or allowed without a prompt.'),
 step('Verify and keep the boundary',['Compare the answer with trial.txt and inspect the file in Notepad to confirm it was not changed.','If you declined a request, inspect whether the read was blocked or an allowed alternative was used. A denial does not prove that no other action occurred.','Keep the original permission setting and record any review controls you could not try.'],'You checked the action’s result and did not infer a policy solely from the absence of a dialog.')],transfer:'Before approving future work, identify its concrete action, target, scope and expected result.'},
 {id:'notifications',area:'Find your way',title:'Follow work through notifications and Activity',minutes:'About 6–10 min',summary:'Try a completion alert, inspect its chat and restore your preferred setting.',source:'notifications',controls:['Settings → Notifications','Turn-completion alerts','Activity bell','Windows notification settings'],steps:[
 {title:'An alert points you to work',body:['Notifications tell you that work needs attention. An alert is not proof that the answer or deliverable is correct. Activity can help locate running, unread or waiting chats.','Use one short text task in a trial chat; no email, SMS or recurring schedule is required.'],expect:'You know where you will inspect the result after an alert.'},
 step('Inspect and choose an alert',['Open Settings and locate Notifications. Note the current completion-alert choice and separate question/permission alert settings.','For this trial, choose completion alerts while the app is in the background, if available. Leave unrelated categories unchanged.','If Windows asks for notification access, decide whether you want to allow it. If blocked, inspect Windows Settings → System → Notifications for the app.'],'You know which app and operating-system settings affect this trial.','If your workspace controls the setting, keep it. A blocked notification is a delivery limitation, not necessarily a failed task.'),
 step('Try and locate the result',['Start a harmless task, such as organizing ten fictional packing items into categories, then move to Notepad while it runs.','Observe whether a completion alert arrives. Return through the alert if available, or open the app manually.','Use the Activity bell if offered and locate the trial chat. Inspect its answer for missing or misclassified items.'],'You can find and assess the result whether or not Windows delivered an alert.'),
 step('Keep a deliberate preference',['Restore the notification choice you changed, or deliberately keep the new setting.','Explain the difference between a completion alert and a question or permission request that needs a response.','Use Activity filters if offered to locate one running, waiting or unread chat; do not clear unrelated unread items for this trial.'],'You can follow work without assuming every notification means success.')],transfer:'Choose alerts that help you return to useful work, then open and check each actual result.'},
 {id:'appshots',area:'See and work',title:'Send an Appshot of the window you mean',minutes:'About 6–10 min',summary:'Capture a fictional Notepad window, inspect its destination and verify what was shared.',source:'appshots',controls:['Appshot hotkey','Frontmost window','Appshot destination','Attachment preview'],steps:[
 {title:'A window capture can contain more than pixels',body:['An Appshot shares the frontmost app window as an image and available text. Some apps expose text beyond the visible area; others provide only a screenshot.','Use a separate Notepad window containing only a fictional picnic list. Do not use private documents for this trial.'],expect:'You understand which window and content you intend to share.'},
 step('Check the capture route',['In ChatGPT settings, find the Appshot hotkey and destination choice. Note their current values.','If you prefer a separate trial chat, select New chat as the destination where offered. Automatic can choose a recently used chat.','Bring the fictional Notepad window to the front and close unrelated tabs in that window.'],'You know where the capture should go and which app is in front.','If Appshots are unavailable, record that separately. A manual screenshot practices image inputs, not the Appshot hotkey.'),
 step('Capture and inspect',['Press both Alt keys together on Windows, or use the configured Appshot hotkey. Complete supported permission setup if requested.','Inspect the destination chat and captured window. Check the image and any available text before adding further instructions.','Ask which picnic items are shown. Compare the reply with your Notepad content and distinguish visible evidence from guesses.'],'You used the Appshot route and checked the actual context and answer.'),
 step('Check the snapshot boundary',['Change one fictional item in Notepad. The earlier Appshot remains a previous capture.','Take another Appshot only if you want to share the updated state; verify the destination again.','Restore the destination preference if you changed it for the trial. Do not assume the capture grants ongoing control of Notepad.'],'You can update visual context deliberately and understand what an Appshot does not establish.')],transfer:'Use an Appshot for a non-sensitive app state that is easier to show than describe, and inspect what was captured.'},
 {id:'local-folders',area:'Organize work',title:'Work with a local folder and inspect the actual files',minutes:'About 10–15 min',summary:'Open a dedicated practice folder, read and edit a file, then verify it outside the chat.',source:'projects',controls:['Open folder','Local project / host','File viewer','File Explorer'],steps:[
 {title:'A local project points to working files',body:['A local project can give a chat access to folders on the selected computer. A ChatGPT project with uploaded sources is a different way to supply context.','Use a dedicated folder so you can identify every trial file. A synced conversation alone does not establish that a different host can access your local files.'],expect:'You can distinguish a local folder from an uploaded source or a conversation transcript.'},
 step('Prepare and open a folder',['In File Explorer, create AI Folder Trial. In Notepad, save packing.txt inside it with three fictional items.','In the desktop app’s Work/Codex local view, use Open folder to select AI Folder Trial. If a trust prompt appears, inspect the path and choose deliberately for this folder you created.','Check the selected computer/host and project. Use the file panel or File Explorer to confirm the folder path.'],'The chat is associated with the intended practice folder.','If your chat runs in a cloud environment without local access, do not assume it can see this folder. Return to the local view or record the feature unavailable.'),
 step('Read a file from disk',['Ask the chat to read packing.txt from the selected folder and list its three items without editing it.','Inspect the file/action details and compare the response with Notepad.','Change one item yourself in Notepad and save. Ask the chat to reread the file rather than rely on its previous response.'],'You observed a read of current disk contents instead of only recalling earlier chat text.'),
 step('Make and inspect one edit',['Ask for one specific change to packing.txt, such as adding a fourth item. Keep the request within this practice file.','Inspect the proposed or recorded change in the file viewer when available.','Reopen the file in Notepad and compare the actual disk contents with the requested edit. Check for unrelated changes.'],'You verified a real file change outside the chat.'),
 step('Leave a useful record',['Keep a short note of the folder path and the final file state if you want to resume later.','Close the file view or return to the app’s project list. Closing a view is not deletion of the folder.','Before a future task, check its selected host and folders again rather than relying on the chat title.'],'You can find your output and identify the context for another local task.')],transfer:'Use a dedicated local project for files an assistant should read or change, and inspect the actual output on disk.'},
 {id:'mentions',area:'Find your way',title:'Select context with @ and inspect what you included',minutes:'About 6–10 min',summary:'Use the composer picker to select one resource and verify the resulting context.',source:'files',controls:['@ picker','Search results','Selected resource','Remove selection'],steps:[
 {title:'A selected resource makes your reference concrete',body:['The @ picker offers resources supported by your current surface, such as files or installed capabilities. Its results vary with your project and access.','For file practice, use a local practice chat containing a harmless packing.txt file. If you need to set one up, follow the local-folder tutorial first.'],expect:'You know which resource you intend to reference before opening the picker.'},
 step('Search and select',['In the composer of the practice chat, type @ and inspect the categories offered.','Search for packing.txt if file selection is supported. Read the result name and path before selecting it.','Inspect the selected resource or mention in the draft. Remove an incorrect selection using its available remove control or by deleting the mention.'],'You can select the intended resource and correct a mistaken selection.','If this picker exposes plugins rather than local files, use its actual categories. File attachment is an alternative way to supply the file, but does not demonstrate @ file selection.'),
 step('Use the selected resource',['Select the intended file and ask for its current packing items.','Inspect the response and any file read details; compare with the actual file. A mention alone does not prove the resource was successfully read.','If access fails, inspect the selected path and current project rather than asking the model to guess the contents.'],'You checked that a concrete selected resource was used.'),
 step('Choose context for another task',['Open @ again and find another resource category you actually have, without connecting an account for this trial.','Dismiss the picker if none is needed. Check the draft for leftover selected resources before sending.','Explain why the packing file was relevant and why unrelated files were left out.'],'You can supply relevant context deliberately without adding everything available.')],transfer:'Select the exact source that changes the answer, check its identity and inspect whether the assistant could actually use it.'},
 {id:'skill-picker',area:'Extend the app',title:'Select an installed skill and check its method',minutes:'About 8–12 min',summary:'Inspect an existing skill, invoke it through the supported picker and assess its result.',source:'plugins',controls:['Skills list','@ in ChatGPT / $ in Codex','Skill selection','Workflow result'],steps:[
 {title:'A skill supplies a repeatable method',body:['A skill packages instructions and supporting resources for a particular task. Select one whose purpose fits the work; naming a skill does not prove its method was followed.','Use an already enabled skill that can work on a small fictional note, such as a recap or writing workflow. Installing or creating a skill is a separate tutorial.'],expect:'You can name a suitable skill and the result its method should produce.'},
 step('Inspect an available skill',['Open the app’s Skills list or the skill picker and read the name and description of a candidate.','Choose one that accepts a short note and produces a result you can inspect without sending messages or changing an external service.','If no suitable skill is installed, record this trial unavailable. Do not select an unrelated skill just to obtain a completed status.'],'You selected an available method that fits the trial input.'),
 step('Invoke through the supported picker',['In Codex, type $ and select the intended enabled skill. In ChatGPT, use @ and select the skill where supported.','Provide a fictional note with two decisions and one unanswered question; ask for the output described by that skill.','Inspect any skill-use indication or explanation of the method and the resulting output. If the skill cannot run, keep that failure distinct from a general response.'],'You invoked the intended skill through your actual surface.','If the selected name stays plain text or the menu is absent, inspect your surface’s skill controls. Do not infer invocation from a familiar-looking answer alone.'),
 step('Check and reuse the method',['Compare the output with the skill’s described process, the two decisions and the unanswered question. Identify any missing or invented detail.','Revise the note with one changed decision and invoke the same skill again. Check that it handles the change while retaining its intended format.','Choose whether this method would save effort on a real recurring task.'],'You tested both the result and the consistency of a reusable method.')],transfer:'Use a skill when a task benefits from a known repeatable process, and check its output against both the method and the source.'}
 );
 lessons.push(
 {id:'documents',area:'Create useful work',title:'Create and revise an editable document',minutes:'About 12–18 min',summary:'Make a short picnic brief, inspect the document and reopen an exported copy.',source:'fileViewer',controls:['Work composer','Generated file / Open','Preview selection / annotation','Download / saved file'],steps:[
 {title:'Choose a document you can edit later',body:['A document file is useful when you want headings, structured text and later editing in a compatible document editor. A chat reply is not itself a DOCX file.','Use this fictional brief: four people; a picnic on Saturday at 12:00; budget 60; each person brings water; meeting point to be confirmed. You will create a one-page brief with an action list and an explicit unresolved meeting point.'],expect:'You know the source facts and what the document must preserve.'},
 step('Create and open the file',['Start a Work chat with file creation available. Give the five brief facts and request an editable DOCX with a title, plan and action list. Use your own wording.','Wait for the generated file and open its file card or preview. Check the actual name and extension.','Find the headings, Saturday time and unresolved meeting point in the document.'],'An actual document opens and contains the intended structure.','If the response only supplies text, ask for the actual file and its saved location. If generation is unavailable, record that rather than treating text as a file.'),
 step('Revise a passage without losing facts',['In a supported preview, select the action list and use its annotation/comment control to request shorter action lines. Otherwise identify that section explicitly in the chat.','Keep the people, time, budget and unresolved meeting point unchanged.','Open the revised file and compare that section and the surrounding facts. Check for clipped text, accidental extra pages or invented decisions.'],'You inspected a focused revision in the document itself.'),
 step('Export and reopen',['Download or save the revised DOCX to a folder you can find. In local mode, identify the actual output path.','Open that copy in a compatible document editor or viewer. Check that it contains the revised action list.','If an editor is available, change the title yourself and save a separate copy to confirm it remains editable; keep the generated original for comparison.'],'You have a usable file outside the chat and can distinguish versions.')],transfer:'Turn a real non-sensitive plan into an editable document, review its unresolved details and keep a clearly named final copy.'},
 {id:'pdf',area:'Create useful work',title:'Create a PDF and inspect every page',minutes:'About 12–18 min',summary:'Build a one-page packing checklist, repair its layout and verify the downloaded PDF.',source:'fileViewer',controls:['Work composer','PDF preview','Page navigation / zoom','Download / saved file'],steps:[
 {title:'A PDF preserves a page layout',body:['Use a PDF when the page should be easy to read or print consistently. Inspect the rendered pages; correct prose in the chat cannot prove that page layout is usable.','Make a fictional one-page packing checklist with six items: water, sandwiches, blanket, plates, a rubbish bag and a first-aid kit. Include a blank tick box beside each item and space for two extra items.'],expect:'You have a small page-based result with visible checks.'},
 step('Create and inspect the PDF',['In a file-capable Work chat, describe the checklist and request an actual one-page PDF.','Open the generated PDF, check its page count and use zoom to inspect all six items and blank writing spaces.','Check the bottom of the page as well as the top. Confirm that boxes, labels and margins are visible.'],'The actual PDF is readable and meets the one-page requirement.','If no PDF preview is available, download the file and inspect it in a local PDF reader. A renamed text file or an answer saying PDF created is not sufficient.'),
 step('Make one layout revision',['Choose an improvement you can observe, such as larger item text or more room beside each tick box. Identify the affected region in the preview where annotations are supported, or describe it in the chat.','Request the revision while keeping the same six items and one-page limit.','Open the revised PDF and check that the change did not push an item onto another page or clip a label.'],'You verified a layout change and its effect on the whole page.'),
 step('Open the saved copy',['Download or save the revised PDF under a clear name. Open that copy from its folder.','Recheck the page count, the final item and both blank entries. Use print preview if you intend to print; printing is optional.','Keep the editable source too if one was provided and you expect to revise the content later.'],'You verified the exported artifact rather than only its in-chat preview.')],transfer:'Create a checklist, handout or itinerary and inspect every exported page before sending or printing it.'},
 {id:'spreadsheets',area:'Create useful work',title:'Build a spreadsheet and test its formulas',minutes:'About 15–20 min',summary:'Create a fictional budget, change a quantity and check that totals recalculate.',source:'fileViewer',controls:['Workbook preview','Sheet / cell selection','Formula field','Edit input','Download XLSX'],steps:[
 {title:'A workbook should calculate, not just look like a table',body:['A spreadsheet can store inputs and use formulas to update results. A displayed total does not establish that it recalculates correctly.','Use a fictional budget of 60 units. Three rows start with quantity 1 each: snacks at 18 units, drinks at 12 and transport at 20. The initial spend should be 50 and the remaining amount 10.'],expect:'You have expected numbers to compare with actual formulas.'},
 step('Create and open a workbook',['In a file-capable Work chat, request an XLSX with Item, Quantity, Unit price and Line total columns, plus budget, total spend and remaining amount. Supply the three rows and require formulas for calculated cells.','Open the generated workbook and locate the sheet and relevant cells.','Check that the starting spend is 50 and remaining amount is 10; inspect the formula field for a line total and the overall total if the viewer exposes it.'],'You located both the inputs and calculated outputs.','If preview editing or formulas are unavailable, download and inspect the XLSX in a compatible spreadsheet editor. A CSV or plain chat table does not preserve workbook formulas in the same way.'),
 step('Change an input and predict the result',['Predict what quantity 2 for snacks should do: snacks become 36, total spend 68 and remaining amount -8.','Change that quantity in an editable workbook view or compatible editor. Check the actual dependent values.','If they do not update, inspect whether the total was typed as a constant, whether formulas reference the intended cells and whether the editor recalculates.'],'The workbook responds correctly to a changed input, or you identified a concrete failure.'),
 step('Repair and retest',['Ask for a repair if needed, identifying the cell/input and observed versus expected values. Keep the three item prices unchanged.','Try quantity 0 for snacks: spend should be 32 and remaining amount 28. Then restore quantity 1 and verify 50 and 10.','Request a clear over-budget indicator if useful; check that it is based on the numeric result, not a manually typed message.'],'You tested more than the starting display and restored known inputs.'),
 step('Save the working version',['Download or save the final XLSX. If you edited a downloaded copy, save it under a new name.','Reopen the saved workbook and repeat one quantity change, then restore it.','Identify the file you will reuse and which cells are intended as inputs.'],'You verified that the reusable file retains its intended calculations.')],transfer:'Build a small non-sensitive tracker and test a changed input, a zero case and a reopened copy before relying on its totals.'},
 {id:'slides',area:'Create useful work',title:'Make a presentation and review every slide',minutes:'About 15–20 min',summary:'Turn a fictional event brief into three slides, revise a crowded slide and verify the export.',source:'fileViewer',controls:['Presentation preview','Slide thumbnails','Selection / annotation','Download PPTX'],steps:[
 {title:'Slides need a readable sequence',body:['A presentation combines a message, order and layout. Review its slides as slides; an outline alone cannot show overlaps or text that is too small.','Use a fictional three-slide picnic proposal: 1. Saturday at 12:00 for four people; 2. budget 60, planned costs 50, reserve 10; 3. packing list and meeting point still to confirm.'],expect:'You know the intended sequence and the numbers each slide should communicate.'},
 step('Create and inspect the deck',['In a file-capable Work chat, provide the brief and request an editable three-slide PPTX with large text and concise headings.','Open its presentation preview. Use thumbnails or slide navigation to inspect all three slides.','Check the time, people, arithmetic and unresolved meeting point; inspect edges, labels and line breaks at a readable zoom.'],'The actual slides communicate the supplied brief without invented details.','If only an outline appears, request the file. If preview is unsupported, open the exported PPTX in a compatible viewer.'),
 step('Revise one slide',['Choose a visible improvement on the budget slide, such as giving costs and reserve separate labeled blocks.','Use a supported slide annotation/selection or identify slide 2 in the chat. Keep the three-slide sequence and all numbers unchanged.','Inspect the revised slide and the other two slides for unintended changes or text overflow.'],'You checked both the requested change and the rest of the deck.'),
 step('Export and present locally',['Download or save the final PPTX and open the saved copy in a compatible presentation app or viewer.','Try slideshow/presentation view if available. Read every slide at presentation size and confirm the order.','Where editing is available, change the title in a separate copy and confirm it is editable text. Do not infer editability from the file extension alone.'],'You have reviewed a usable exported deck, including its display outside the chat.')],transfer:'Prepare a small briefing with one main point per slide, inspect every slide and rehearse from the exported version.'},
 {id:'visuals',area:'Create useful work',title:'Explore an interactive visualization',minutes:'About 10–15 min',summary:'Operate a budget explorer, test its numbers and request a focused improvement.',source:'visualizations',controls:['@Visualize','Interactive result','Numeric inputs','Reset / keyboard controls'],steps:[
 {title:'Use interaction to explore a relationship',body:['An interactive visual helps when changing an input should reveal what happens. A static illustration does not provide working controls.','Build a small picnic budget explorer: total budget 60, snacks 18, drinks 12 and transport 20. It should show total cost and remaining budget, with labeled numeric inputs and a Reset control.'],expect:'You can describe the inputs, outputs and relationship you want to explore.'},
 step('Select Visualize and open the result',['In a supported ChatGPT desktop Chat/Work chat, type @, search Visualize and select the matching Plugins entry.','Describe the explorer in your own words and include the starting values. Request a text explanation alongside the controls.','Wait for the result and locate the actual inputs. Check that the initial outputs are 50 total cost and 10 remaining.'],'You have an interactive result that can be inspected, not only an image.','If Visualize is absent in desktop, try the supported web surface or record unavailable. A plain table is a useful fallback but does not demonstrate this feature.'),
 step('Explore and check behavior',['Change snacks from 18 to 36. Predict and verify total cost 68 and remaining amount -8.','Set all costs to zero and verify the total is zero and remaining amount 60. Try Reset and inspect the restored values.','Use Tab and the keyboard to reach and change the inputs; inspect whether labels and focus are clear.'],'The controls change the result correctly and you have tried a boundary case.'),
 step('Refine and compare',['Choose one improvement, such as an over-budget text label alongside its color. Request it in the same chat.','Inspect the revised result; it may be a new version. Repeat the over-budget test and check the text label.','Keep your source values available. Do not assume the result stays synchronized with future changes in another file or source.'],'You tested the revision instead of assuming a new appearance preserved behavior.')],transfer:'Use an interactive visual to explore a decision with changing inputs, and check known values before trusting the relationship.'},
 {id:'sites',area:'Create useful work',title:'Build and test a Site before publishing',minutes:'About 15–25 min',summary:'Save a packing-checklist website version, test it in preview and return to the saved work.',source:'siteCreation',controls:['@Sites / website request','Saved version','Preview','Edit','Sites list'],steps:[
 {title:'A preview lets you review the website first',body:['Sites can build a website from your description. A saved version and a published deployment are different states; deployment URLs are live production deployments.','Use a fictional packing checklist website with six labeled items, a count of checked items and Reset. Keep it a review version without deploying. For this trial, checks may reset on reload; no accounts or permanent visitor records are needed.'],expect:'You know what to build and have separated preview review from publishing.'},
 step('Create a saved version',['In supported ChatGPT desktop or web, select @Sites where offered or describe the website you want.','Specify the six items, count, Reset, a narrow-screen layout and a saved version without deployment.','Open the resulting preview/version. Inspect its stated save and deployment status; do not treat a production deployment link as a private preview.'],'You can identify the review version and its available preview.','If Sites is unavailable, record that. A locally generated HTML page can practice web development, but is not proof you used Sites.'),
 step('Test normal and empty states',['Tick two items and verify the count becomes two. Clear them with Reset and verify zero.','Use keyboard navigation to reach the checkboxes and Reset. Narrow the preview or window and check that controls and item labels still fit.','Reload the preview and observe the check state. Reset-on-reload is acceptable for this stated trial; saved visitor progress was not requested.'],'You inspected both interaction and the stated persistence behavior.'),
 step('Revise one part',['Use Edit in the preview where available, or continue the same chat, to request a clearer count label and larger checkbox targets.','Keep the item list, Reset behavior and no-deployment boundary.','Inspect the revised version and repeat the two-item and Reset tests.'],'You verified that a focused revision preserved the intended behavior.'),
 step('Return to the saved Site',['Open the Sites view in the desktop app, or More → Sites on the web, and locate the saved website.','Reopen the intended version and inspect its title, content and deployment status.','Keep it saved for the separate publishing tutorial. Do not claim visitor access or durable user progress from a successful preview test.'],'You can find your saved website again and explain what has and has not been published.')],transfer:'Build a small website for a real need, define its empty states and storage expectations, and test a saved version before deciding to publish.'}
 );
 lessons.push(
 {id:'plugins',area:'Extend the app',title:'Browse, install and manage a plugin',minutes:'About 8–12 min',summary:'Inspect a directory entry, install it deliberately and locate its capabilities in a new chat.',source:'pluginDirectory',controls:['Plugins directory','Plugin details','Install / +','Installed','@ picker','Uninstall'],steps:[
 {title:'A plugin is an installable package',body:['A plugin can bundle reusable skills and tools. Installation makes that package available; a service connection and its permissions are separate.','This trial uses the Google Drive directory entry as a concrete example. You will inspect and manage the package. The next tutorial covers actually connecting a storage account and reading a trial document.'],expect:'You can distinguish a package from an authorized service account.'},
 step('Inspect before installing',['Open Plugins in the desktop app. Search Google Drive and open the matching entry.','Read its provider, included capabilities, supported surfaces and connection requirements. Compare them with a task you might use, such as reading one document.','Check Installed to see whether this package is already present. Note its original state so you do not uninstall something you were already using.'],'You have inspected the intended package and its current installation state.','If the directory or this plugin is unavailable, record that. Do not install a similarly named unverified entry just to complete the trial.'),
 step('Install and locate the capability',['Use the directory’s install / plus control if it is not already installed. Read any setup screen; connecting an account is a separate deliberate decision.','Start a new chat after installation, type @ and locate the installed plugin or its available capabilities.','Select it in a draft and inspect the selected name. If authentication is required, identify the connection request rather than claiming the service can already be read.'],'You can locate the installed package in a supported chat.','Managed/default plugins may not offer installation changes. Inspect their available state without treating workspace policy as an error.'),
 step('Keep or undo the installation',['Return to the Installed list and reopen the plugin details.','If installed only for this trial and you do not plan to continue, use Uninstall when offered and verify its absence from Installed. Otherwise keep it for the connection tutorial.','Do not infer that uninstalling a package revoked a separately connected account. Inspect those connections separately.'],'You can manage this package and explain which account setup remains undone.')],transfer:'Choose plugins by their concrete capabilities and connection requirements, and keep only packages you intend to use.'},
 {id:'connections',area:'Extend the app',title:'Connect a storage account and read a trial document',minutes:'About 12–18 min',summary:'Authorize Google Drive deliberately, retrieve a fictional document and inspect the source.',source:'pluginDirectory',controls:['Plugin connection / Connect','Account selection','Consent permissions','@Google Drive','Connection management'],steps:[
 {title:'Choose the identity and resource',body:['A service connection gives supported tools access through a particular account. This is different from the desktop Settings → Connections area for remote computers.','Use a Google Drive account you control and a new document containing only fictional trial data. This exercise reads that document; it does not send messages, share files or request account-wide cleanup.'],expect:'You know which identity and document you intend to use.'},
 step('Prepare a source you can verify',['In your own Google Drive, create a document named AI connection trial. Add three fictional packing items and a distinctive marker such as Picnic trial 482.','Confirm that you can open the document in your browser and note its title or link.','Open the Google Drive plugin’s connection/setup controls in ChatGPT. If it is not installed, complete the plugin-installation tutorial first.'],'You have an accessible source and a way to verify any retrieved answer.'),
 step('Review and connect',['Use Connect or the offered account-authorization route. Check the account identity, service domain and requested permissions before accepting.','Enter credentials only in the service’s sign-in/consent flow, not in a chat message. Continue only if you want the displayed access.','Inspect the connection status and account identity afterward. If a workspace provides a managed identity, do not assume it is your personal Drive account.'],'You know which connection is active and the access you agreed to.','If the requested access is not acceptable, cancel and record unavailable for this trial. A connected label still does not prove access to a particular document.'),
 step('Retrieve and verify one document',['Start a supported chat, select Google Drive with @ where offered, and ask it to read only AI connection trial using the supplied title/link. Request the marker and packing items with a source link.','Inspect the actual tool activity and open the cited document. Compare its title, marker and items with the original.','If access fails, check account identity, document permissions and connection status; do not accept a guessed list as a successful connection test.'],'You verified a real read from the intended account and source.'),
 step('Manage the trial connection',['Return to the plugin’s account/connection management controls. Locate the account used and its available disconnect control.','If this was a new trial connection you do not want to keep, disconnect it and inspect the resulting state. Preserve unrelated pre-existing connections.','If you keep it, record that deliberate choice. Removing the plugin and disconnecting its service authorization are different actions; the service may also expose its own access-management page.'],'You can find the connection lifecycle controls and know whether your trial access remains active.')],transfer:'For a real connected task, identify the account, narrow the source and verify the retrieved result against that source.'},
 {id:'skills',area:'Extend the app',title:'Create, test and revise your own skill',minutes:'About 15–25 min',summary:'Build a small instruction-only note workflow, inspect its saved instructions and test two cases.',source:'skillAuthoring',controls:['Skills','@skill-creator / $skill-creator','Saved SKILL.md / skill details','Skill picker','Edit / enable controls'],steps:[
 {title:'Capture one method you want to repeat',body:['Create a skill named picnic-note-recap for fictional event notes. Its method should produce three headings: Decisions, Open questions and Next step. It must not invent a date, owner or answer absent from the note.','Keep this trial instruction-only, without scripts, tools or external connections. Selecting an existing skill and authoring your own are separate activities.'],expect:'You have defined the method, trigger and output you want to reuse.'},
 step('Create a draft in a known scope',['Open a practice project in the supported desktop app. Inspect Skills and choose the creation route, or select @skill-creator in ChatGPT Work / $skill-creator in Codex.','Describe picnic-note-recap, its three headings, its use for event notes and its no-invention rule. Request instruction-only behavior.','Before saving, identify whether the skill belongs to this project or a broader personal/workspace location. Use the narrowest offered scope that suits your trial.'],'You can identify where the draft will be saved.','If the creator or saving controls are unavailable, record that. Text describing a skill is not evidence that it was installed.'),
 step('Inspect the saved instructions',['Open the skill’s details or saved SKILL.md using the reported path. Read its name, description and method.','Check that its trigger is specific to note recaps and that it includes all three headings and the no-invention rule.','Confirm there are no unwanted scripts or external dependencies. Use the creator/editor to repair the draft if needed.'],'You reviewed the reusable instructions rather than only the creator’s summary.'),
 step('Try two distinct cases',['In a fresh supported chat, select the saved skill from the skill picker. Supply a fictional note: Four people agreed to bring sandwiches; the meeting point is undecided.','Check Decisions, Open questions and Next step. No exact meeting place or assigned owner should be invented.','Invoke the same skill with a second note that includes a confirmed place and no unresolved questions. Check that it reports no open questions rather than copying the previous note.'],'You tested the saved method against both an incomplete and a complete note.'),
 step('Revise and manage it',['If either case failed, revise the skill instructions through the owning editor/creator and rerun that failed case in a fresh chat.','Locate its available enable/disable or removal controls. If you do not want to keep the trial, disable only this skill through its supported controls; ask for help identifying its exact scope if needed.','If you keep it, record its name and scope so you can select or revise it later.'],'You can maintain the actual saved skill and verify a change through another trial.')],transfer:'Turn one repeated personal workflow into a narrowly scoped skill, then test a normal case and a case with missing information.'},
 {id:'mcp',area:'Extend the app',title:'Connect a documentation MCP server and inspect its tools',minutes:'About 12–18 min',summary:'Add OpenAI’s public read-only documentation server, make a real lookup and manage the trial entry.',source:'mcpSetup',references:['mcpSetup','docsMcp'],controls:['Settings → MCP servers','Add server','Streamable HTTP','Restart','/mcp','Server enable controls'],steps:[
 {title:'MCP connects a model to actual tools',body:['Model Context Protocol lets a server describe tools and handle their requests. A registered server, a connected server and a successful tool call are different things to verify.','Use OpenAI’s public documentation server at https://developers.openai.com/mcp. It searches and reads documentation; it does not run OpenAI API requests for you. No API key or private account data is needed for this server.'],expect:'You know the exact service and the read-only activity you intend to test.'},
 step('Register the intended server',['In the desktop app’s Codex settings, open MCP servers and inspect existing entries first. Reuse an existing matching OpenAI documentation entry rather than creating a duplicate.','If absent, choose Add server, name it openai-docs-trial, select Streamable HTTP and enter https://developers.openai.com/mcp. Save, then use the offered Restart action.','Keep other servers unchanged. Do not supply a token or run an unrelated downloaded server command for this public HTTP trial.'],'The intended URL is registered, with its original/new status known.','If settings are managed or this surface lacks the setup route, record unavailable. A pasted URL in an ordinary chat does not register a server.'),
 step('Inspect connected tools',['Start or reopen a supported Codex chat and enter /mcp. Locate the documentation server’s connection status.','Inspect the available tools and identify its search and page-retrieval capabilities by their actual names.','If it cannot connect, read its error and check the URL and network policy. Keep configuration success distinct from a working connection.'],'You can distinguish a configured entry from tools available in the current session.'),
 step('Run and verify a lookup',['Request a lookup through that MCP server for the current official instructions for adding an MCP server in the desktop app. Ask it to read the matching documentation page and cite it.','Inspect activity for the actual server tools. Open the cited official page and compare the steps with what you did.','If ordinary web search was used instead, the answer may still help, but this did not demonstrate an MCP tool call. Report the tool limitation rather than inferring success.'],'You verified a documentation tool result and its source.'),
 step('Manage only your trial entry',['Return to MCP settings. If you added openai-docs-trial only for practice, use its disable/remove control where offered and restart as requested. If keeping it, make that choice deliberately.','Inspect /mcp again to check its resulting availability in the refreshed session.','Preserve any entry that was already configured before your trial. Removing one direct server entry does not uninstall unrelated plugin packages.'],'You understand the entry’s lifecycle and have left its final state deliberately.')],transfer:'Before relying on an MCP integration, inspect its server identity, connection status, actual tools and one verified result.'}
 );
 const remaining=typeof module!=='undefined'?require('./feature-lessons-remaining.js'):root.QuestRemainingFeatureLessons;
 lessons.push(...remaining.lessons);
 for(const lesson of lessons){lesson.reviewed='27 October 2026';lesson.steps[lesson.steps.length-1].finish=true;lesson.finishLabel='I tried this feature myself';}
 lessons.find(lesson=>lesson.id==='usage').references=['pricing','commands'];
 lessons.find(lesson=>lesson.id==='plan-mode').references=['prompting','commands'];
 const api={lessons};if(typeof module!=='undefined')module.exports=api;else root.QuestFeatureLessons=api;
})(typeof window!=='undefined'?window:globalThis);
